 "content": "from functools import lru_cache

# Tile the nonzero mask with 2x2 squares and L trominoes. Color 1 marks
# squares; colors 2,3,4 encode the missing corner of the L's 2x2 box.
def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    shapes = []
    for r in range(h):
        for c in range(w):
            sq = frozenset((r+dr,c+dc) for dr in range(2) for dc in range(2))
            if all(x in cells for x in sq): shapes.append((sq,1))
            # missing top-left=2, bottom-left=3, top-right=4; missing bottom-right=5
            for miss,color in [((0,0),2),((1,0),3),((0,1),4),((1,1),5)]:
                s = frozenset((r+dr,c+dc) for dr in range(2) for dc in range(2) if (dr,dc)!=miss)
                if s <= cells: shapes.append((s,color))
    bycell = {p: [] for p in cells}
    for i,(s,col) in enumerate(shapes):
        for p in s: bycell[p].append(i)
    @lru_cache(None)
    def solve(rem):
        if not rem: return ()
        R=set(rem)
        p=min(R)
        for i in bycell[p]:
            s,col=shapes[i]
            if s <= R:
                rest=solve(tuple(sorted(R-s)))
                if rest is not None: return ((i,)+rest)
        return None
    sol=solve(tuple(sorted(cells)))
    if sol is None: raise ValueError('mask cannot be tiled')
    out=[[0]*w for _ in range(h)]
    for i in sol:
        s,col=shapes[i]
        for r,c in s: out[r][c]=col
    return out
